/* an efficiency gauge for the trap cards (box 640 × 330): needle at the value */
function TH_gauge(v,col,lab){const cx=320,cy=290,r=190,pt=(p,rr)=>{const a=Math.PI*(1-p/100);return [cx+rr*Math.cos(a),cy-rr*Math.sin(a)]};
 const [ax,ay]=pt(v,r);let s=`<path d="M${cx-r},${cy} A${r},${r} 0 0 1 ${cx+r},${cy}" fill="none" stroke="#DEE2E6" stroke-width="26"/>`;
 s+=`<path d="M${cx-r},${cy} A${r},${r} 0 0 1 ${ax.toFixed(1)},${ay.toFixed(1)}" fill="none" stroke="${col}" stroke-width="26"/>`;
 [0,25,50,75,100].forEach(p=>{const [x,y]=pt(p,r+36);s+=TH_T(x.toFixed(1),(y+8).toFixed(1),p+'%',{fs:20,fw:700,a:'middle',fill:TH_GREY})});
 const [nx,ny]=pt(v,64);s+=TH_L(cx,cy,nx.toFixed(1),ny.toFixed(1),'#18213A',6)+`<circle cx="${cx}" cy="${cy}" r="12" fill="#18213A"/>`;
 s+=TH_T(cx,cy-92,'η = '+v.toFixed(1)+'%',{fs:34,fw:800,a:'middle',fill:col})+TH_T(cx,cy+34,lab,{fs:22,fw:700,a:'middle',fill:'#18213A'});
 return s}
/* the Dual loop of the worked example on p-v (box 640 × 330) with an MEP rectangle from v = va to v₁ of height pm */
function TH_dualMep(va,pm,col,lab){const A=TH_pv(70,270,520,230,.9,65),v1=.861,v2=.0615,v4=.0984,iso=(pa,v0,a,bb)=>Array.from({length:31},(_,i)=>{const v=a+(bb-a)*i/30;return [A.X(v),A.Y(pa*Math.pow(v0/v,1.4))]});
 let s=A.ax+TH_T(74,30,'p (bar)',{fs:20,fw:700,fill:TH_GREY})+TH_T(590,300,'v',{fs:22,fw:700,a:'end',fill:TH_GREY});
 s+=`<rect x="${A.X(va).toFixed(1)}" y="${A.Y(pm).toFixed(1)}" width="${(A.X(v1)-A.X(va)).toFixed(1)}" height="${(A.Y(0)-A.Y(pm)).toFixed(1)}" fill="${col}" fill-opacity=".45"/>`;
 s+=TH_pl(iso(1,v1,v1,v2),TH_BLUE,4)+TH_L(A.X(v2),A.Y(40.23),A.X(v2),A.Y(60.35),TH_REDC,4)+TH_L(A.X(v2),A.Y(60.35),A.X(v4),A.Y(60.35),TH_REDC,4)+TH_pl(iso(60.35,v4,v4,v1),TH_ORNG,4)+TH_L(A.X(v1),A.Y(2.896),A.X(v1),A.Y(1),TH_BLUE,4);
 s+=TH_L(A.X(va),A.Y(0)+14,A.X(v1),A.Y(0)+14,col,3)+TH_L(A.X(va),A.Y(0)+6,A.X(va),A.Y(0)+22,col,3)+TH_L(A.X(v1),A.Y(0)+6,A.X(v1),A.Y(0)+22,col,3);
 s+=TH_T(A.X(v2)+20,A.Y(60.35)+30,'Dual loop',{fs:22,fw:700,fill:TH_BLUE})+TH_T(440,184,lab,{fs:22,fw:800,a:'middle',fill:col})+TH_T(440,152,'MEP '+pm.toFixed(2)+' bar',{fs:24,fw:800,a:'middle',fill:col});
 return s}
function EXTRA(R,ICON){
 /* hook: a jet engine whose turbine hands about half its work back to the compressor along the shaft */
 ICON.thJet=(x,y)=>`<g transform="translate(${x-165} ${y-70})">${TH_gt({lab:1})}
  <path d="M270,182 L270,250 L50,250 L50,196" fill="none" stroke="#E64980" stroke-width="7" stroke-linejoin="round"/><polygon points="50,182 38,204 62,204" fill="#E64980"/>
  ${TH_T(160,290,'40 to 60% of the turbine work',{fs:22,fw:800,a:'middle',fill:'#E64980'})}${TH_T(160,318,'turns the compressor',{fs:22,fw:800,a:'middle',fill:'#E64980'})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.thRecB=(x,y)=>{const B=TH_braytonTs(60,290,330,250),X=B.X,Y=B.Y;return `<g transform="translate(${x} ${y}) scale(1.1) translate(-210 -165)">${TH_L(60,290,400,290,TH_DARK,3)}${TH_L(60,290,60,20,TH_DARK,3)}
  ${TH_L(X(0),Y(300),X(0),Y(543.4),TH_BLUE,5)}${TH_pl(B.hp,TH_REDC,5)}${TH_L(X(B.s3),Y(1200),X(B.s3),Y(662.5),TH_ORNG,5)}${TH_pl(B.lp,TH_BLUE,5)}
  ${TH_dot(X(0),Y(300),'#18213A',8)}${TH_dot(X(0),Y(543.4),'#18213A',8)}${TH_dot(X(B.s3),Y(1200),'#18213A',8)}${TH_dot(X(B.s3),Y(662.5),'#18213A',8)}
  ${TH_T(X(0)-14,Y(300)+8,'1',{fs:24,fw:800,a:'end'})}${TH_T(X(0)-14,Y(543.4)+8,'2',{fs:24,fw:800,a:'end'})}${TH_T(X(B.s3)+14,Y(1200)+8,'3',{fs:24,fw:800})}${TH_T(X(B.s3)+14,Y(662.5)+8,'4',{fs:24,fw:800})}
  ${TH_T(160,Y(1000),'8 bar',{fs:24,fw:800,fill:TH_REDC})}${TH_T(250,Y(360),'1 bar',{fs:24,fw:800,fill:TH_BLUE})}${TH_T(66,40,'T',{fs:24,fw:800,fill:TH_GREY})}${TH_T(396,320,'s',{fs:24,fw:800,a:'end',fill:TH_GREY})}</g>`};
 ICON.thRecS=(x,y)=>{const X=v=>70+(v-.3)/.62*320,Y=p=>290-p/6.6*250,iso=(T,a,bb)=>Array.from({length:25},(_,i)=>{const v=a+(bb-a)*i/24;return [X(v),Y(.287*T/v/100)]});
  return `<g transform="translate(${x} ${y}) scale(1.1) translate(-210 -165)">${TH_L(60,290,400,290,TH_DARK,3)}${TH_L(60,290,60,20,TH_DARK,3)}
  ${TH_pl(iso(900,.4305,.861),TH_REDC,5)}${TH_pl(iso(300,.861,.4305),TH_BLUE,5)}${TH_L(X(.4305),Y(2),X(.4305),Y(6),TH_GRNC,5,'stroke-dasharray="10 7"')}${TH_L(X(.861),Y(3),X(.861),Y(1),TH_GRNC,5,'stroke-dasharray="10 7"')}
  ${[[.861,1,'1'],[.4305,2,'2'],[.4305,6,'3'],[.861,3,'4']].map(([v,p,n])=>TH_dot(X(v),Y(p),'#18213A',8)+TH_T(X(v)+(v<.5?-14:14),Y(p)+8,n,{fs:24,fw:800,a:v<.5?'end':'start'})).join('')}
  <path d="M${X(.84)},${Y(2.2)} Q${X(.64)},${Y(3.4)} ${X(.46)},${Y(4.2)}" fill="none" stroke="${TH_GRNC}" stroke-width="4"/>${TH_arrow(X(.5),Y(3.95),X(.45),Y(4.25),TH_GRNC,4)}
  ${TH_T(X(.66),Y(2.45),'regenerator',{fs:22,fw:800,a:'middle',fill:TH_GRNC})}${TH_T(X(.6),Y(5.0)-40,'900 K',{fs:24,fw:800,fill:TH_REDC})}${TH_T(X(.6),Y(.45),'300 K',{fs:24,fw:800,fill:TH_BLUE})}
  ${TH_T(66,40,'p',{fs:24,fw:800,fill:TH_GREY})}${TH_T(396,320,'v',{fs:24,fw:800,a:'end',fill:TH_GREY})}</g>`};
 ICON.thRecM=(x,y)=>{const A=TH_pv(60,290,340,240,.9,50),O=TH_ottoPts(A),x1=A.X(O.v1),x2=A.X(O.v2),ym=A.Y(6);return `<g transform="translate(${x} ${y}) scale(1.1) translate(-210 -165)">${A.ax}
  <rect x="${x2.toFixed(1)}" y="${ym.toFixed(1)}" width="${(x1-x2).toFixed(1)}" height="${(A.Y(0)-ym).toFixed(1)}" fill="${TH_GRNC}" fill-opacity=".4"/>
  ${TH_pl(O.c,TH_BLUE,5)}${TH_L(x2,A.Y(18.38),x2,A.Y(48.09),TH_REDC,5)}${TH_pl(O.e,TH_ORNG,5)}${TH_L(x1,A.Y(2.617),x1,A.Y(1),TH_BLUE,5)}
  ${TH_T(300,ym-50,'same area',{fs:24,fw:800,a:'middle',fill:TH_GRNC})}${TH_T(66,40,'p',{fs:24,fw:800,fill:TH_GREY})}${TH_T(396,320,'v',{fs:24,fw:800,a:'end',fill:TH_GREY})}</g>`};
}
